        (3000, 'check my balance', 'Let me check my balance first, okay?')
    ) AS expected(id, expression_text, sentence_text)
    LEFT JOIN writing_expression we ON we.id = expected.id
    WHERE we.id IS NULL
       OR we.target_expression_text IS DISTINCT FROM expected.expression_text
       OR we.representative_sentence_text IS DISTINCT FROM expected.sentence_text;

    IF mismatched > 0 THEN
        RAISE EXCEPTION 'LAN-471 pronunciation assets: % writing_expression rows are missing or differ from the texts the audio was generated from (first id %). V94 must use the 2026-09-10 revised expression SQL.',
            mismatched, first_mismatch;
    END IF;
END
$$;

ON CONFLICT (writing_expression_id, accent_locale) DO UPDATE SET
    expression_audio_url = EXCLUDED.expression_audio_url,
    sentence_audio_url = EXCLUDED.sentence_audio_url,
    words = EXCLUDED.words,
    updated_at = now();

DO $$
BEGIN
    IF (SELECT count(*) FROM expression_pronunciation_asset
        WHERE writing_expression_id BETWEEN 2259 AND 3000) <> 2226 THEN
        RAISE EXCEPTION 'LAN-471 pronunciation assets: expected 2226 rows for 2259~3000';
    END IF;

    IF EXISTS (
        SELECT 1 FROM expression_pronunciation_asset
        WHERE writing_expression_id BETWEEN 2259 AND 3000
        GROUP BY accent_locale
        HAVING count(*) <> 742
    ) OR (SELECT count(DISTINCT accent_locale) FROM expression_pronunciation_asset
          WHERE writing_expression_id BETWEEN 2259 AND 3000) <> 3 THEN
        RAISE EXCEPTION 'LAN-471 pronunciation assets: every accent locale must have 742 rows';
    END IF;

    IF EXISTS (
        SELECT 1 FROM expression_pronunciation_asset
        WHERE writing_expression_id BETWEEN 2259 AND 3000
          AND sentence_audio_url IS NULL
    ) THEN
        RAISE EXCEPTION 'LAN-471 pronunciation assets: sentence audio URL is missing';
    END IF;

    IF (SELECT count(*) FROM expression_pronunciation_asset
        WHERE writing_expression_id BETWEEN 2259 AND 3000
          AND expression_audio_url IS NULL) <> 231 THEN
        RAISE EXCEPTION 'LAN-471 pronunciation assets: expected 231 templated expressions without expression audio';
    END IF;
END
$$;
